'use strict';

/**
* Evaluate the cis function for a double-precision complex floating-point number.
*
* @module @stdlib/math-base-special-ccis
*
* @example
* import Complex128 from '@stdlib/complex-float64-ctor';
* import ccis from '@stdlib/math-base-special-ccis';
*
* var z = new Complex128( 0.0, 0.0 );
* // returns <Complex128>
*
* var out = ccis( z );
* // returns <Complex128>[ 1.0, 0.0 ]
*
* @example
* import Complex128 from '@stdlib/complex-float64-ctor';
* import ccis from '@stdlib/math-base-special-ccis';
*
* var z = new Complex128( 1.0, 0.0 );
* // returns <Complex128>
*
* var out = ccis( z );
* // returns <Complex128>[ ~0.540, ~0.841 ]
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import assign from './assign.js';
import strided from './strided.js';


// MAIN //

setReadOnly( main, 'assign', assign );
setReadOnly( main, 'strided', strided );


// EXPORTS //

export default main;

// exports: { "assign": "main.assign", "strided": "main.strided" }
